// GA4 プロパティID: 数字だけ（「properties/123」も可）。G- で始まる測定ID（Measurement ID）は別物
// GA4 対象サイトURL: http(s) の URL（スキームが無ければ https:// を補う）。ホストは siteHost の規則（www は区別）
function ga4SiteCheck(v){var s=String(v||'').trim();if(!s)return{url:''};if(!/^[a-z][a-z0-9+.-]*:\/\//i.test(s))s='https://'+s;var L=window.AirReachKeywordList;var h=L?L.siteHost(s):'';if(!h||h.indexOf('.')<0)return{error:'GA4 対象サイトURLを https://example.com/ の形で入力してください。'};return{url:s,host:h}}
function renderGa4Target(){var el=q('ga4-target');if(!el)return;var p=ga4PropertyCheck(val('ga-property')),st=ga4SiteCheck(val('ga4-site'));el.textContent='GA4 プロパティID：'+(p.error?'（数字のIDを入力）':(p.id||'未設定'))+' ／ 対象サイト：'+(st.error?'（URLを入力）':(st.url?st.url+'（'+st.host+'）':'未設定'))}
// GA4 の行を取り込む。site（siteUrl）があれば、そのホストの行だけで ga4Sites の要素を作り端末の基準値に記録する（無ければ Studio 内だけ）
function importGa4(rows,opt){opt=opt||{};var L=window.AirReachKeywordList;var st=ga4SiteCheck(opt.siteUrl);var r=null;if(L&&st.url&&!st.error){r=L.ga4SiteFromRows(rows,{propertyId:opt.propertyId,siteUrl:st.url,periodDays:opt.periodDays||28,source:opt.source||'api',allowHostless:opt.source==='csv'})}var useRows=r&&r.entry?r.entry.rows:rows;/* 対象サイトの行が無いときも Studio 内には残す（サイト未紐付け。診断には使わない） */mapGa4(useRows,r&&r.entry?{host:r.entry.host,propertyId:r.entry.propertyId}:null);if(r&&r.entry){try{var b=JSON.parse(localStorage.getItem('airreach_official_baseline_v1')||'null')||{evidenceClass:'Official',source:'Studio measurements',periodDays:28,keywords:[]};b.ga4Sites=L.mergeGa4Sites(b.ga4Sites,[r.entry]);localStorage.setItem('airreach_official_baseline_v1',JSON.stringify(b))}catch(e){}}save();return r}

function ga4PropertyCheck(v){var s=String(v||'').trim().replace(/^properties\//,'');if(!s)return{id:''};if(/^G-/i.test(s))return{error:'「G-」で始まる測定ID（Measurement ID）ではなく、数字だけのプロパティID（例: 123456789）を入力してください。'};if(!/^\d{1,20}$/.test(s))return{error:'GA4 プロパティIDは数字だけです（例: 123456789）。'};return{id:s}}

// ---- 競合と比べる（無料診断と同じ方法で、自社と競合の公開ページを診断して並べる） ----
function topOf(u){try{var x=new URL(/^https?:\/\//i.test(u)?u:'https://'+u);return x.origin+'/'}catch(e){return u}}
function hostLabel(u){try{return new URL(/^https?:\/\//i.test(u)?u:'https://'+u).hostname.replace(/^www\./,'')}catch(e){return u}}
// 既定はトップページどうしで比べる（個別ページと比べると不公平）。「入力したページのまま」を選んだときだけ URL をそのまま使う
function compareSites(asIs){var self=state.profile.url||val('orch-url')||'';var list=[];var pick=function(u){return asIs?u:topOf(u)};if(self)list.push({role:'self',name:state.profile.brand||'自社',url:pick(self),input:self});(state.competitors||[]).slice(0,5).forEach(function(c){if(c.url)list.push({role:'comp',name:c.name||'',url:pick(c.url),input:c.url})});return list}
async function runCompare(){var el=q('compare-status');if(el)el.hidden=false;var asIs=!!(q('compare-asis')&&q('compare-asis').checked);var sites=compareSites(asIs);if(!sites.length||sites[0].role!=='self'){if(el){el.className='ars-note warn';el.textContent='基本情報に自社のURLを入れてください。'}return}if(sites.length<2){if(el){el.className='ars-note warn';el.textContent='競合を1件以上追加してください。'}return}if(!window.AirReach||!window.AirReach.diagnose){if(el){el.className='ars-note warn';el.textContent='診断の部品を読み込めませんでした。再読み込みしてください。'}return}var allow=!!(q('compare-proxy')&&q('compare-proxy').checked);if(el){el.className='ars-note';el.textContent='診断しています…（'+sites.length+'サイト・1サイト10〜20秒）'}var b=q('run-compare');if(b)b.disabled=true;var out=[];for(var i=0;i<sites.length;i++){var s=sites[i];if(el)el.textContent='診断しています… '+(i+1)+' / '+sites.length+'：'+s.url;try{var d=await window.AirReach.diagnose(s.url,{allowProxy:allow,subpages:false});out.push({role:s.role,name:s.name,url:s.url,input:s.input,ok:true,overall:d.overall,factors:{structure:d.structure,entity:d.entity,faq:d.faq,discover:d.discover},checks:(d.checks||[]).map(function(c){return{factor:c.factor,label:c.label,tip:c.tip,state:c.state,max:c.max}}),title:d.page&&d.page.title||''})}catch(e){out.push({role:s.role,name:s.name,url:s.url,input:s.input,ok:false,error:e&&e.message?e.message:String(e)})}}state.compare={at:new Date().toISOString(),mode:asIs?'asis':'top',sites:out};if(b)b.disabled=false;var fails=out.filter(function(x){return !x.ok}).length;if(el){el.className='ars-note'+(fails?' warn':' good');el.textContent='診断しました（'+(out.length-fails)+' / '+out.length+' サイト）。'+(fails?'取得できなかったサイトがあります。「取得に同意」にチェックを入れて再度お試しください。':'')}save()}
function renderCompare(){var el=q('compare-result');if(!el)return;var c=state.compare;if(!c||!c.sites||!c.sites.length){el.innerHTML='<p class="ars-gnote">「形式を点検して並べる」を押すと、自社と競合のトップページを同じ基準で点検して並べます（参考）。</p>';return}var F=(window.AirReach&&window.AirReach.FACTORS)||[{id:'structure',label:'ページの骨格'},{id:'entity',label:'会社・サービス情報'},{id:'faq',label:'よくある質問'},{id:'discover',label:'見つけやすさ'}];function sc(v){return v==null?'<span class="ars-cmp-na">—</span>':'<b>'+esc(v)+'</b>'}var self=c.sites.filter(function(s){return s.role==='self'})[0];var head='<tr><th>サイト</th><th>総合</th>'+F.map(function(f){return '<th>'+esc(f.label)+'</th>'}).join('')+'</tr>';var rows=c.sites.map(function(s){var nm=s.role==='self'?'<span class="ars-cmp-self">自社</span> ':'';var label=nm+esc(s.name||hostLabel(s.url))+(s.role==='comp'&&!s.name?' <span class="ars-cmp-noname">名前未入力</span>':'')+'<div class="ars-cmp-url">診断: '+esc(s.url)+'</div>'+(s.input&&s.input!==s.url?'<div class="ars-cmp-url">入力: '+esc(s.input)+'</div>':'');if(!s.ok)return '<tr><td>'+label+'</td><td colspan="'+(F.length+1)+'" class="ars-cmp-na">取得できませんでした（'+esc(s.error||'')+'）</td></tr>';var diff=function(v,k){if(s.role==='self'||!self||!self.ok||v==null)return '';var sv=k==='overall'?self.overall:self.factors[k];if(sv==null)return '';var d=v-sv;return d>0?' <span class="ars-cmp-up">自社より+'+d+'</span>':''};return '<tr'+(s.role==='self'?' class="is-self"':'')+'><td>'+label+'</td><td>'+sc(s.overall)+diff(s.overall,'overall')+'</td>'+F.map(function(f){return '<td>'+sc(s.factors[f.id])+diff(s.factors[f.id],f.id)+'</td>'}).join('')+'</tr>'}).join('');
var gapHtml='';if(self&&self.ok){var miss={};c.sites.forEach(function(s){if(s.role!=='comp'||!s.ok)return;s.checks.forEach(function(ch){if(ch.state!=='ok')return;var mine=self.checks.filter(function(x){return x.label===ch.label})[0];if(!mine||mine.state!=='ng')return;var k=ch.label;miss[k]=miss[k]||{label:ch.label,tip:ch.tip,max:ch.max,factor:ch.factor,who:[]};miss[k].who.push(s.name||s.url)})});var ms=Object.keys(miss).map(function(k){return miss[k]}).sort(function(a,b){return (b.who.length-a.who.length)||((b.max||0)-(a.max||0))});var fl={};F.forEach(function(f){fl[f.id]=f.label});gapHtml='<h4 class="ars-cmp-h">競合にあって自社に無いもの（'+ms.length+'件）</h4>'+(ms.length?'<ul class="ars-cmp-gaps">'+ms.map(function(m){return '<li><strong>'+esc(m.label)+'</strong><span class="ars-cmp-tag">'+esc(fl[m.factor]||m.factor)+' · 最大'+esc(m.max)+'点</span><div class="ars-gnote">'+esc(m.tip||'')+'</div><div class="ars-gnote">できている競合：'+esc(m.who.join('、'))+'</div></li>'}).join('')+'</ul>':'<p class="ars-gnote">競合にあって自社に無い項目はありません。</p>')}
el.innerHTML='<div class="ars-table-wrap"><table class="ars-table ars-cmp"><thead>'+head+'</thead><tbody>'+rows+'</tbody></table></div><p class="ars-gnote">'+esc((function(){try{var d=new Date(c.at);return d.getFullYear()+'/'+(d.getMonth()+1)+'/'+d.getDate()+' '+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')}catch(e){return ''}})())+' 時点・'+(c.mode==='asis'?'入力したページ':'各サイトのトップページ')+'の公開情報だけで判定した参考値です（AIの回答に出るかとは別物です）。'+(c.sites.some(function(x){return x.role==='comp'&&!x.name})?'名前未入力の競合は、名前を入れると AI計測で比べられます。':'')+'</p>'+gapHtml}
// ---- AI計測: 競合と比べる（SOV）とダッシュボードへの受け渡し ----
function promptVersion(prompts){var t=(prompts||[]).map(function(p){return p.prompt}).sort().join('\n');var h=0;for(var i=0;i<t.length;i++){h=(h*31+t.charCodeAt(i))|0}return 'studio-'+(h>>>0).toString(16)}
var PROVIDER_ID={ChatGPT:'openai',Claude:'claude',Perplexity:'perplexity',Gemini:'gemini'};
function latestObservedRun(){var rs=(state.hack2||[]).filter(function(r){return r.run_id&&String(r.evidenceClass||'')!=='Estimated'&&!matchEngine(r.engine||r.model||r.provider,'Jev')});if(!rs.length)return null;var last=rs.reduce(function(m,r){return r.run_id>m?r.run_id:m},'');return rs.filter(function(r){return r.run_id===last})}
function sovStats(rows){var by={};rows.forEach(function(r){var e=r.engine||'AI';var b=by[e]||(by[e]={engine:e,model:r.model||'',n:0,self:0,cited:0,judged:0,comp:{}});b.n++;b.self+=n(r.mentioned);if(r.cited!==null&&r.cited!==undefined){b.judged++;b.cited+=n(r.cited)}(r.competitors||[]).forEach(function(c){b.comp[c.name]=(b.comp[c.name]||0)+n(c.mentioned)})});return Object.keys(by).map(function(k){var b=by[k];var compSum=Object.keys(b.comp).reduce(function(s,x){return s+b.comp[x]},0);b.sov=(b.self+compSum)?Math.round(b.self/(b.self+compSum)*1000)/10:null;return b})}
function sovHtml(){var rows=latestObservedRun();if(!rows)return '';var hasComp=rows.some(function(r){return (r.competitors||[]).length});var stats=sovStats(rows);var names=[];stats.forEach(function(b){Object.keys(b.comp).forEach(function(x){if(names.indexOf(x)<0)names.push(x)})});var when=String(rows[0].run_id||'').replace('studio-','');var head='<tr><th>AI</th><th>自社の名前が出た</th>'+names.map(function(x){return '<th>'+esc(x)+'</th>'}).join('')+'<th>SOV</th></tr>';var body=stats.map(function(b){return '<tr><td>'+esc(b.engine)+'</td><td>'+b.self+' / '+b.n+'回</td>'+names.map(function(x){return '<td>'+(b.comp[x]||0)+' / '+b.n+'回</td>'}).join('')+'<td><b>'+(b.sov==null?'—':b.sov+'%')+'</b></td></tr>'}).join('');var client=null;try{client=JSON.parse(sessionStorage.getItem('airreach_studio_client_v1')||'null')}catch(e){}return '<div class="ars-card ars-sov" style="grid-column:1/-1"><h3>競合と比べる（SOV）</h3>'+(hasComp?'<p class="ars-gnote" style="margin:0 0 8px">最新の計測（'+esc((function(){var d=new Date(when);return isNaN(d)?'':d.getFullYear()+'/'+(d.getMonth()+1)+'/'+d.getDate()+' '+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')})())+'）。SOV＝自社の名前が出た回数 ÷（自社＋競合の名前が出た回数の合計）。</p><div class="ars-table-wrap"><table class="ars-table ars-cmp"><thead>'+head+'</thead><tbody>'+body+'</tbody></table></div>':'<p class="ars-gnote" style="margin:0">競合に名前を登録してから計測すると、AIの回答に自社と競合のどちらが出たかを比べます（「競合」画面で名前を入れてください）。</p>')+(client&&client.id&&(function(){var lr=latestObservedRun();return lr&&lr[0]&&window.AirReachStudioClients&&window.AirReachStudioClients.savedRun&&window.AirReachStudioClients.savedRun(lr[0].run_id)})()?'<p class="ars-gnote" style="margin:10px 0 0">✓ この計測は、顧客の「AI計測の記録」に保存済みです（月次レポートに使えます）。</p>':client&&client.id?'<div class="ars-row" style="margin-top:10px"><button id="sov-send" class="ars-btn ars-btn-secondary" type="button">この計測をダッシュボード（'+esc(client.name||'顧客')+'）に送る</button></div>':'<p class="ars-gnote" style="margin:8px 0 0">ダッシュボードの顧客画面から Studio を開くと、この計測を顧客の月次レポートに送れます。</p>')+'</div>'}
function measureSummary(rows){var stats=sovStats(rows);var selfHost='';try{selfHost=new URL(state.profile.url).hostname.replace(/^www\./,'')}catch(e){}var dom={},tc=[];rows.forEach(function(r){var pid=PROVIDER_ID[r.engine]||String(r.engine||'').toLowerCase();var seen={};(r.citations||[]).forEach(function(u){var h='';try{h=new URL(u).hostname.replace(/^www\./,'')}catch(e){return}if(!seen[h]){seen[h]=1;dom[h]=dom[h]||{};dom[h][pid]=(dom[h][pid]||0)+1}if(selfHost&&(h===selfHost||h.slice(-selfHost.length-1)==='.'+selfHost))tc.push({provider:pid,query:r.prompt||r.keyword||'',url:u,match_type:'self_host'})})});var cited=Object.keys(dom).map(function(h){return[h,dom[h]]}).sort(function(a,b){var t=function(x){return Object.keys(x[1]).reduce(function(s,k){return s+x[1][k]},0)};return t(b)-t(a)});return{cited_domains:cited,target_citations:tc,run_id:rows[0].run_id,generated_at:new Date().toISOString(),query_set_version:rows[0].query_set_version||'',source:'studio',competitors:((state.competitors||[]).filter(function(c){return c.name}).map(function(c){return c.name})),by:stats.map(function(b){var cr={};Object.keys(b.comp).forEach(function(x){cr[x]=Math.round(b.comp[x]/b.n*1000)/10});return{provider:PROVIDER_ID[b.engine]||String(b.engine).toLowerCase(),model:b.model,group:'main',label:'Studio',denominator:b.n,judged:b.judged,either:{rate:b.judged?Math.round(b.cited/b.judged*1000)/10:null,numerator:b.cited},service_mention_rate:Math.round(b.self/b.n*1000)/10,sov:b.sov,competitor_mention_rates:cr,error_count:0}})}}
function bindSovSend(){var b=q('sov-send');if(!b)return;b.onclick=function(){var rows=latestObservedRun();var client=null;try{client=JSON.parse(sessionStorage.getItem('airreach_studio_client_v1')||'null')}catch(e){}if(!rows||!client||!client.id)return;try{sessionStorage.setItem('airreach_studio_measure_v1',JSON.stringify({clientId:client.id,clientName:client.name||'',measuredOn:new Date().toISOString().slice(0,10),summary:measureSummary(rows)}))}catch(e){alert('受け渡しに失敗しました');return}location.href='/airreach/app/#/c/'+client.id}}
// ---- 競合と「AIの回答」で比べる（競合比較の中心）。同じ質問への AI の回答に、自社と競合のどちらの名前・サイトが出たか ----
function runAiCompare(){var named=(state.competitors||[]).filter(function(c){return c.name});var el=q('ai-compare-status');if(el)el.hidden=false;if(!named.length){if(el){el.className='ars-note warn';el.textContent='競合に名前を入れてください（AIの回答に出てくる呼び方）。'}return}var engines=[];document.querySelectorAll('[data-cmp-engine]:checked').forEach(function(x){engines.push(x.value)});if(!engines.length){if(el){el.className='ars-note warn';el.textContent='AIを1つ以上選んでください。'}return}runHack2Measure({engines:engines,statusId:'ai-compare-status'})}
function citedHosts(r){return (r.citations||[]).map(function(u){try{return {url:u,host:new URL(u).hostname.replace(/^www\./,'')}}catch(e){return null}}).filter(Boolean)}
function renderAiCompare(){var el=q('ai-compare-result');if(!el)return;var rows=latestObservedRun();var named=(state.competitors||[]).filter(function(c){return c.name});if(!rows||!rows.some(function(r){return (r.competitors||[]).length})){el.innerHTML='<p class="ars-gnote">'+(named.length?'「AIの回答で比べる」を押すと、キーワードから作った質問（最大6問）を選んだAIに聞き、回答に自社と競合（'+esc(named.map(function(c){return c.name}).join('、'))+'）のどちらが出たかを比べます。':'まず上で競合の名前を入れてください。名前が AIの回答に出たかで比べます。')+'</p>';return}
var stats=sovStats(rows);var names=[];stats.forEach(function(b){Object.keys(b.comp).forEach(function(x){if(names.indexOf(x)<0)names.push(x)})});var brand=state.profile.brand||'自社';
var sum='<div class="ars-table-wrap"><table class="ars-table ars-cmp"><thead><tr><th>AI</th><th>'+esc(brand)+'（自社）</th>'+names.map(function(x){return '<th>'+esc(x)+'</th>'}).join('')+'<th>自社の割合（SOV）</th></tr></thead><tbody>'+stats.map(function(b){return '<tr><td>'+esc(b.engine)+'</td><td>'+b.self+' / '+b.n+'問</td>'+names.map(function(x){return '<td>'+(b.comp[x]||0)+' / '+b.n+'問</td>'}).join('')+'<td><b>'+(b.sov==null?'—':b.sov+'%')+'</b>'+(b.sov!=null&&(b.self+Object.keys(b.comp).reduce(function(t,x){return t+b.comp[x]},0))<5?'<div class="ars-gnote">回数が少なく参考値</div>':'')+'</td></tr>'}).join('')+'</tbody></table></div>';
var compHosts={};(state.competitors||[]).forEach(function(c){if(c.name&&c.url){try{compHosts[new URL(/^https?:\/\//i.test(c.url)?c.url:'https://'+c.url).hostname.replace(/^www\./,'')]=c.name}catch(e){}}});var selfHost='';try{selfHost=new URL(state.profile.url).hostname.replace(/^www\./,'')}catch(e){}
var mark=function(v){return v?'<span class="ars-cmp-yes">出た</span>':'<span class="ars-cmp-no">—</span>'};
var detail=rows.map(function(r){var cites=citedHosts(r);var selfC=cites.filter(function(c){return selfHost&&(c.host===selfHost||c.host.endsWith('.'+selfHost))});var compC=cites.filter(function(c){return Object.keys(compHosts).some(function(h){return c.host===h||c.host.endsWith('.'+h)})});var src=r.citeMethod==='none'?'<span class="ars-gnote">出典は測っていない（検索なし）</span>':(cites.length?((selfC.length?'<div>自社: '+selfC.slice(0,2).map(function(c){return '<a href="'+esc(c.url)+'" target="_blank" rel="noopener noreferrer">'+esc(c.url.replace(/^https?:\/\//,'').slice(0,60))+'</a>'}).join('<br>')+'</div>':'')+(compC.length?'<div>競合: '+compC.slice(0,3).map(function(c){return '<a href="'+esc(c.url)+'" target="_blank" rel="noopener noreferrer">'+esc(c.url.replace(/^https?:\/\//,'').slice(0,60))+'</a>'}).join('<br>')+'</div>':'')+(!selfC.length&&!compC.length?'<span class="ars-gnote">自社・競合以外のサイトが出典</span>':'')):'<span class="ars-gnote">出典URLは取得できない（本文で判定）</span>');var cm={};(r.competitors||[]).forEach(function(c){cm[c.name]=c.mentioned});return '<tr><td>'+esc(r.engine)+'</td><td class="ars-cmp-q">'+esc(r.prompt||r.keyword||'')+'</td><td>'+mark(r.mentioned)+'</td>'+names.map(function(x){return '<td>'+mark(cm[x])+'</td>'}).join('')+'<td class="ars-cmp-src">'+src+'</td></tr>'}).join('');
var lost=rows.filter(function(r){return !r.mentioned&&(r.competitors||[]).some(function(c){return c.mentioned})});
var lostHtml=lost.length?'<h4 class="ars-cmp-h">競合だけが出た質問（'+lost.length+'件）— ここが直す対象</h4><ul class="ars-cmp-gaps">'+lost.map(function(r){return '<li><strong>'+esc(r.prompt||r.keyword)+'</strong><span class="ars-cmp-tag">'+esc(r.engine)+'</span><div class="ars-gnote">出た競合: '+esc((r.competitors||[]).filter(function(c){return c.mentioned}).map(function(c){return c.name}).join('、'))+'</div>'+(r.answer_excerpt?'<div class="ars-gnote">回答の冒頭: '+esc(String(r.answer_excerpt).slice(0,160))+'…</div>':'')+'</li>'}).join('')+'</ul>':'<p class="ars-gnote">競合だけが出た質問はありません。</p>';
var d=new Date(String(rows[0].run_id||'').replace('studio-',''));var when=isNaN(d)?'':d.getFullYear()+'/'+(d.getMonth()+1)+'/'+d.getDate()+' '+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');
el.innerHTML='<p class="ars-gnote" style="margin:0 0 8px">'+esc(when)+' の計測・'+rows.length+'回答。SOV＝自社の名前が出た回数 ÷（自社＋競合の名前が出た回数）。</p>'+sum+lostHtml+'<h4 class="ars-cmp-h">質問ごとの結果</h4><div class="ars-table-wrap"><table class="ars-table ars-cmp"><thead><tr><th>AI</th><th>質問</th><th>自社</th>'+names.map(function(x){return '<th>'+esc(x)+'</th>'}).join('')+'<th>出典</th></tr></thead><tbody>'+detail+'</tbody></table></div>'}
