function renderContext(){var el=q('ars-context');if(!el)return;var client=null;try{client=JSON.parse(sessionStorage.getItem('airreach_studio_client_v1')||'null')}catch(e){}var url=(state.profile&&state.profile.url)||val('orch-url')||'';var host='';try{host=url?new URL(/^https?:\/\//i.test(url)?url:'https://'+url).hostname.replace(/^www\./,''):''}catch(e){}el.innerHTML=(client&&client.name?'<span class="ars-ctx-client">'+esc(client.name)+'</span>':'')+(host?'<span class="ars-ctx-site">'+esc(host)+'</span>':'<span class="ars-ctx-empty">対象サイト未設定</span>')}
function initApp(){var res=q('orch-result');var sync=function(){var has=!!(res&&!res.hidden);document.body.classList.toggle('has-job',has)};sync();var ran=false;var run=q('orch-run');if(run)run.addEventListener('click',function(){ran=true});if(res&&window.MutationObserver)new MutationObserver(function(){sync();if(ran&&!res.hidden){ran=false;gotoPanel('result')}}).observe(res,{attributes:true,attributeFilter:['hidden']});document.querySelectorAll('[data-goto]').forEach(function(b){b.addEventListener('click',function(){gotoPanel(b.getAttribute('data-goto'))})});var kf=q('ars-key-form');if(kf){try{q('ars-key').value=localStorage.getItem('airreach_studio_key_v1')||''}catch(e){}kf.addEventListener('submit',function(e){e.preventDefault();try{localStorage.setItem('airreach_studio_key_v1',q('ars-key').value.trim())}catch(e2){}var m=q('ars-key-msg');if(m)m.textContent='保存しました'})}var menu=document.querySelector('.ars-appbar-menu');document.addEventListener('click',function(e){if(menu&&menu.open&&!menu.contains(e.target))menu.open=false});renderContext();var ou=q('orch-url');if(ou)ou.addEventListener('input',renderContext);window.addEventListener('load',function(){sync();if(!location.hash&&res&&!res.hidden){var b=document.querySelector('.ars-side button[data-panel="result"]');if(b){b._silent=true;b.click()}}renderContext()})}
document.addEventListener('DOMContentLoaded',initApp);
